      if (node.querySelector) {
        const spans = node.querySelectorAll('span');
        for (let i = 0; i < spans.length; i++) {
          if (isGifLabel(spans[i])) return spans[i];
        }
        const divs = node.querySelectorAll('div');
        for (let i = 0; i < divs.length; i++) {
