      .replace(/[_-]thumb(?:nail)?[_-]?/i, '')
      .replace(/[_-]small[_-]?/i, '')
      .replace(/[_-]preview[_-]?/i, '')
      .replace(/[_-]\d+x\d+[_-]?/i, '')
      .replace(/[_-]s\d+[_-]?/i, '')
      .replace(/[_-]w\d+[_-]?/i, '')
